def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    seeds = {}
    for r, (ra, rb) in enumerate(row_spans):
        for c, (ca, cb) in enumerate(col_spans):
            colors = {grid[y][x] for y in range(ra, rb) for x in range(ca, cb)} - {0, 8}
            for color in colors:
                seeds.setdefault(color, set()).add((r, c))

    lines = {color: set() for color in seeds}
    for color, points in seeds.items():
        for r, c in points:
            same_row = [cc for rr, cc in points if rr == r]
            same_col = [rr for rr, cc in points if cc == c]
            if len(same_row) >= 2:
                lines[color].update((r, cc) for cc in range(min(same_row), max(same_row) + 1))
            if len(same_col) >= 2:
                lines[color].update((rr, c) for rr in range(min(same_col), max(same_col) + 1))

    out = [row[:] for row in grid]
    for r, (ra, rb) in enumerate(row_spans):
        for c, (ca, cb) in enumerate(col_spans):
            covering = [color for color, cells in lines.items() if (r, c) in cells]
            if covering:
                value = 6 if 2 in covering and 3 in covering else covering[0]
                for y in range(ra, rb):
                    for x in range(ca, cb):
                        out[y][x] = value
    return out
